package com.example.lab.accounting.outbox;
import com.example.lab.payment.kafka.PaymentEvent; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant;
@Service public class SagaOutboxService { private final SagaOutboxRepository repo; private final ObjectMapper mapper; public SagaOutboxService(SagaOutboxRepository r,ObjectMapper m){repo=r;mapper=m;} @Transactional public void enqueue(PaymentEvent e){try{repo.save(SagaOutbox.pending(e.eventType(),e.paymentId().toString(),mapper.writeValueAsString(e)));}catch(Exception x){throw new IllegalStateException("cannot serialize saga event",x);}} public long count(SagaOutbox.Status s){return repo.count(s);} @Transactional public void recover(){repo.findAll().stream().filter(x->x.getStatus()==SagaOutbox.Status.PROCESSING).forEach(SagaOutbox::requeue);} }
